// server/src/core/ctx.ts
init_connection();
async function buildApplicationContext(applicationId) {
  const app = await q1(
    `SELECT a.*, c.name AS customer_name, c.dob, c.employment_type, c.business_name,
            c.annual_income, c.monthly_income, c.business_turnover, c.credit_score,
            c.risk_class, c.pan, c.city, c.state,
            p.name AS product_name, p.max_amount AS product_max, p.max_tenure AS product_max_tenure,
            p.min_amount AS product_min, p.min_tenure AS product_min_tenure
     FROM applications a
     JOIN customers c ON c.id = a.customer_id
     JOIN products p ON p.id = a.product_id
     WHERE a.id = ?`,
    [applicationId]
  );
  if (!app) return {};
  const bureau = await q1("SELECT * FROM bureau_reports WHERE customer_id = ? ORDER BY id DESC LIMIT 1", [app.customer_id]);
  const bank = await q1("SELECT * FROM bank_analyses WHERE application_id = ? ORDER BY id DESC LIMIT 1", [applicationId]);
  const gst = await q1("SELECT * FROM gst_profiles WHERE customer_id = ? ORDER BY id DESC LIMIT 1", [app.customer_id]);
  const docs = await q1("SELECT COUNT(*) AS n FROM documents WHERE application_id = ? AND status = 'verified'", [applicationId]);
  const exposure = await q1(
    `SELECT COALESCE(SUM(outstanding), 0) AS total FROM loans WHERE customer_id = ? AND status NOT IN ('closed', 'written_off')`,
    [app.customer_id]
  );
  const age = app.dob ? Math.floor((Date.now() - new Date(app.dob).getTime()) / (365.25 * 864e5)) : null;
  return {
    "application.id": app.id,
    "application.requested_amount": app.requested_amount,
    "application.tenure": app.tenure,
    "application.purpose": app.purpose,
    "application.stage": app.stage,
    "customer.name": app.customer_name,
    "customer.age": age,
    "customer.dob": app.dob,
    "customer.employment_type": app.employment_type,
    "customer.monthly_income": app.monthly_income,
    "customer.annual_income": app.annual_income,
    "customer.business_turnover": app.business_turnover,
    "customer.credit_score": app.credit_score ?? bureau?.score ?? null,
    "customer.risk_class": app.risk_class,
    "customer.city": app.city,
    "customer.state": app.state,
    "customer.pan": app.pan,
    "product.category": app.product_name,
    "product.max_amount": app.product_max,
    "product.max_tenure": app.product_max_tenure,
    "credit.score": bureau?.score ?? null,
    "credit.dpd_max": bureau?.dpd_max ?? 0,
    "credit.total_outstanding": bureau?.total_outstanding ?? 0,
    "credit.utilization": bureau?.credit_utilization ?? 0,
    "credit.enquiries_6m": bureau?.enquiries_6m ?? 0,
    "credit.writeoffs": bureau?.writeoffs ?? 0,
    "credit.settlements": bureau?.settlements ?? 0,
    "credit.overdue_accounts": bureau?.overdue_accounts ?? 0,
    "bank.monthly_income": bank?.monthly_income ?? null,
    "bank.monthly_expense": bank?.monthly_expense ?? null,
    "bank.avg_balance": bank?.avg_balance ?? null,
    "bank.emi_obligations": bank?.emi_obligations ?? 0,
    "bank.surplus": bank?.banking_surplus ?? null,
    "bank.bounce_count": bank?.bounce_count ?? 0,
    "bank.cash_deposits": bank?.cash_deposits ?? 0,
    "bank.turnover": bank?.turnover ?? 0,
    "gst.turnover": gst?.turnover ?? null,
    "gst.filing_status": gst?.filing_status ?? null,
    "gst.declared_vs_banking_pct": gst?.declared_vs_banking_pct ?? null,
    "documents.verified": docs?.n ?? 0,
    "exposure.total": exposure?.total ?? 0
  };
}
function capacityMetrics(ctx) {
  const income = Number(ctx["bank.monthly_income"] ?? ctx["customer.monthly_income"] ?? 0);
  const obligations = Number(ctx["bank.emi_obligations"] ?? 0);
  const surplus = Number(ctx["bank.surplus"] ?? income - obligations);
  const foir = income > 0 ? Math.round(obligations / income * 100 * 10) / 10 : null;
  const dscr = obligations > 0 ? Math.round(surplus / obligations * 100) / 100 : null;
  return { income, obligations, surplus, foir, dscr };
}

// server/src/core/bre.ts
function resolvePath(ctx, path3) {
  if (path3 in ctx) return ctx[path3];
  const parts = path3.split(".");
  let cur = ctx;
  for (const p of parts) {
    if (cur === null || cur === void 0) return void 0;
    if (typeof cur === "object") cur = cur[p];
    else return void 0;
  }
  return cur;
}
function toNum(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string") {
    const n = Number(v.replace(/[^0-9.\-]/g, ""));
    return Number.isFinite(n) ? n : null;
  }
  return null;
}
function evalLeaf(cond, ctx) {
  const raw = resolvePath(ctx, cond.field);
  const n = toNum(raw);
  switch (cond.operator) {
    case "eq":
      return String(raw) === String(cond.value) ? null : `${cond.field} expected ${cond.value}, got ${String(raw)}`;
    case "neq":
      return String(raw) !== String(cond.value) ? null : `${cond.field} must not equal ${String(cond.value)}`;
    case "gte":
      return n !== null && n >= cond.value ? null : `${cond.field} must be >= ${cond.value} (got ${String(raw)})`;
    case "gt":
      return n !== null && n > cond.value ? null : `${cond.field} must be > ${cond.value} (got ${String(raw)})`;
    case "lte":
      return n !== null && n <= cond.value ? null : `${cond.field} must be <= ${cond.value} (got ${String(raw)})`;
    case "lt":
      return n !== null && n < cond.value ? null : `${cond.field} must be < ${cond.value} (got ${String(raw)})`;
    case "between":
      return n !== null && n >= cond.min && n <= cond.max ? null : `${cond.field} must be between ${cond.min} and ${cond.max} (got ${String(raw)})`;
    case "in":
      return (cond.values ?? []).some((v) => String(v) === String(raw)) ? null : `${cond.field} must be one of [${(cond.values ?? []).join(", ")}]`;
    case "not_in":
      return !(cond.values ?? []).some((v) => String(v) === String(raw)) ? null : `${cond.field} must not be in [${(cond.values ?? []).join(", ")}]`;
    case "contains":
      return typeof raw === "string" && raw.toLowerCase().includes(String(cond.value).toLowerCase()) ? null : `${cond.field} must contain "${cond.value}"`;
    default:
      return null;
  }
}
function evaluateConditions(cond, ctx, failures) {
  if ("children" in cond) {
    if (cond.operator === "not") {
      const childPassed = evaluateConditions(cond.children[0], ctx, []);
      if (childPassed) failures.push(`NOT(${describe(cond.children[0])}) failed`);
      return !childPassed;
    }
    const results = cond.children.map((c) => evaluateConditions(c, ctx, failures));
    if (cond.operator === "and") return results.every(Boolean);
    return results.some(Boolean);
  }
  const fail = evalLeaf(cond, ctx);
  if (fail) failures.push(fail);
  return fail === null;
}
function describe(cond) {
  if ("children" in cond) return cond.operator.toUpperCase();
  const l = cond;
  return `${l.field} ${l.operator} ${l.value ?? l.min ?? l.values ?? ""}`;
}
function evaluateRule(rule, ctx) {
  const failures = [];
  const passed = evaluateConditions(rule.conditions, ctx, failures);
  return {
    passed,
    failures,
    matchedRules: passed ? [{ code: rule.code, name: rule.name, priority: rule.priority }] : []
  };
}
function evaluateRuleSet(rules, ctx) {
  const sorted = [...rules].sort((a, b) => a.priority - b.priority || a.id - b.id);
  const reasons = [];
  let riskGrade = "standard";
  for (const rule of sorted) {
    const res = evaluateRule(rule, ctx);
    if (!res.passed) {
      reasons.push(`${rule.name}: ${res.failures.join("; ")}`);
      return { eligible: false, reasons, riskGrade, failedRule: rule.code };
    }
    if (rule.action.riskGrade) {
      const grades = ["low", "standard", "medium", "high"];
      const gi = grades.indexOf(rule.action.riskGrade);
      const ci = grades.indexOf(riskGrade);
      if (gi > ci) riskGrade = rule.action.riskGrade;
    }
  }
  reasons.push("All policy rules passed");
  return { eligible: true, reasons, riskGrade };
}
function renderCondition(cond, depth = 0) {
  if ("children" in cond) {
    if (cond.operator === "not") return `NOT (${renderCondition(cond.children[0], depth)})`;
    const sep = cond.operator === "and" ? " AND " : " OR ";
    return cond.children.map((c) => renderCondition(c, depth + 1)).join(sep);
  }
  const l = cond;
  const fmtField = l.field.split(".").pop().replace(/_/g, " ");
  switch (l.operator) {
    case "between":
      return `${fmtField} between ${l.min} and ${l.max}`;
    case "in":
      return `${fmtField} in [${(l.values ?? []).join(", ")}]`;
    case "not_in":
      return `${fmtField} not in [${(l.values ?? []).join(", ")}]`;
    case "contains":
      return `${fmtField} contains "${l.value}"`;
    case "eq":
      return `${fmtField} = ${l.value}`;
    case "neq":
      return `${fmtField} \u2260 ${l.value}`;
    case "gte":
      return `${fmtField} \u2265 ${l.value}`;
    case "gt":
      return `${fmtField} > ${l.value}`;
    case "lte":
      return `${fmtField} \u2264 ${l.value}`;
    case "lt":
      return `${fmtField} < ${l.value}`;
    default:
      return fmtField;
  }
}

