reconRouter.post("/recon/:id/match", requirePerm("payments.*"), asyncH(async (req, res) => {
  const body = z8.object({ payment_id: z8.number().int().positive() }).parse(req.body);
  const tx3 = await q1("SELECT * FROM recon_transactions WHERE id = ? AND tenant_id = ?", [req.params.id, req.user.tenant_id]);
  if (!tx3) {
    res.status(404).json({ error: "Transaction not found" });
    return;
  }
  if (tx3.status === "reversed") {
    res.status(400).json({ error: "Reversed transactions cannot be matched" });
    return;
  }
  const pay = await q1(
    `SELECT p.*, l.loan_no, c.name AS customer_name FROM payments p JOIN loans l ON l.id = p.loan_id JOIN customers c ON c.id = p.customer_id
     WHERE p.id = ? AND p.tenant_id = ?`,
    [body.payment_id, req.user.tenant_id]
  );
  if (!pay) {
    res.status(404).json({ error: "Payment not found" });
    return;
  }
  if (pay.amount !== tx3.amount) {
    res.status(400).json({ error: `Amount mismatch \u2014 transaction ${tx3.amount}, payment ${pay.amount}` });
    return;
  }
  const already = await q1("SELECT * FROM recon_transactions WHERE payment_id = ? AND tenant_id = ? AND status = 'matched'", [pay.id, req.user.tenant_id]);
  if (already) {
    res.status(400).json({ error: `Payment already matched by transaction #${already.id}` });
    return;
  }
  await run(
    "UPDATE recon_transactions SET status = 'matched', match_type = 'manual', payment_id = ?, loan_id = ?, customer_id = ?, confidence = 1, reconciled_at = ?, note = NULL WHERE id = ?",
    [pay.id, pay.loan_id, pay.customer_id, now(), tx3.id]
  );
  await audit({ tenantId: req.user.tenant_id, userId: req.user.id, action: "recon.match", entityType: "recon_transaction", entityId: tx3.id, before: { status: tx3.status }, after: { payment_id: pay.id, receipt_no: pay.receipt_no }, ip: clientIp(req) });
  res.json(await q1("SELECT * FROM recon_transactions WHERE id = ?", [tx3.id]));
}));
reconRouter.post("/recon/:id/unmatch", requirePerm("payments.*"), asyncH(async (req, res) => {
  const tx3 = await q1("SELECT * FROM recon_transactions WHERE id = ? AND tenant_id = ?", [req.params.id, req.user.tenant_id]);
  if (!tx3) {
    res.status(404).json({ error: "Transaction not found" });
    return;
  }
  if (tx3.status !== "matched") {
    res.status(400).json({ error: "Only matched transactions can be unmatched" });
    return;
  }
  await run("UPDATE recon_transactions SET status = 'unmatched', match_type = 'none', payment_id = NULL, loan_id = NULL, customer_id = NULL, confidence = NULL, reconciled_at = NULL WHERE id = ?", [tx3.id]);
  await audit({ tenantId: req.user.tenant_id, userId: req.user.id, action: "recon.unmatch", entityType: "recon_transaction", entityId: tx3.id, before: { status: tx3.status, payment_id: tx3.payment_id }, after: { status: "unmatched" }, ip: clientIp(req) });
  res.json({ ok: true });
}));
reconRouter.post("/recon/:id/reverse", requirePerm("payments.reverse"), asyncH(async (req, res) => {
  const body = z8.object({ reason: z8.string().min(3) }).parse(req.body);
  const tx3 = await q1("SELECT * FROM recon_transactions WHERE id = ? AND tenant_id = ?", [req.params.id, req.user.tenant_id]);
  if (!tx3) {
    res.status(404).json({ error: "Transaction not found" });
    return;
  }
  if (tx3.status === "reversed") {
    res.status(400).json({ error: "Already reversed" });
    return;
  }
  let reversedPayment = false;
  if (tx3.payment_id) {
    const pay = await q1("SELECT * FROM payments WHERE id = ?", [tx3.payment_id]);
    if (pay && !pay.reversed) {
      await run("UPDATE payments SET reversed = 1, reversal_reason = ?, status = 'reversed' WHERE id = ?", [body.reason, pay.id]);
      const allocs = await q("SELECT * FROM payment_allocations WHERE payment_id = ?", [pay.id]);
      for (const a of allocs) {
        if (a.installment_id) {
          const inst = await q1("SELECT * FROM installments WHERE id = ?", [a.installment_id]);
          if (inst) {
            const newPaid = Math.max(0, inst.paid_amount - a.amount);
            await run("UPDATE installments SET paid_amount = ?, paid = 0, status = 'pending', paid_at = NULL WHERE id = ?", [newPaid, inst.id]);
          }
        }
      }
      await refreshLoanState(pay.loan_id);
      reversedPayment = true;
    }
  }
  await run("UPDATE recon_transactions SET status = 'reversed', reversed_at = datetime('now'), note = ? WHERE id = ?", [body.reason, tx3.id]);
  await audit({ tenantId: req.user.tenant_id, userId: req.user.id, action: "recon.reverse", entityType: "recon_transaction", entityId: tx3.id, before: { status: tx3.status, payment_id: tx3.payment_id }, after: { reason: body.reason, reversed_payment: reversedPayment }, ip: clientIp(req) });
  res.json({ ok: true, reversed_payment: reversedPayment });
}));
reconRouter.post("/recon/:id/resolve", requirePerm("payments.*"), asyncH(async (req, res) => {
  const body = z8.object({ note: z8.string().min(2) }).parse(req.body);
  const tx3 = await q1("SELECT * FROM recon_transactions WHERE id = ? AND tenant_id = ?", [req.params.id, req.user.tenant_id]);
  if (!tx3) {
    res.status(404).json({ error: "Transaction not found" });
    return;
  }
  await run("UPDATE recon_transactions SET note = ?, status = CASE WHEN status = 'requires_review' THEN 'unmatched' ELSE status END WHERE id = ?", [body.note, tx3.id]);
  await audit({ tenantId: req.user.tenant_id, userId: req.user.id, action: "recon.resolve", entityType: "recon_transaction", entityId: tx3.id, after: body, ip: clientIp(req) });
  res.json({ ok: true });
}));
