init_connection();
import { Router as Router9 } from "express";
import { z as z9 } from "zod";
var portalRouter = Router9();
portalRouter.use(authRequired);
function scopedCustomer(req) {
  const u = req.user;
  if (u.role !== "customer") return null;
  if (!u.customer_id) return null;
  return { id: u.customer_id };
}
function requireCustomer(req) {
  return scopedCustomer(req);
}
portalRouter.get("/portal/summary", asyncH(async (req, res) => {
  const me = requireCustomer(req);
  if (!me) {
    res.status(403).json({ error: "Portal available for customer accounts only" });
    return;
  }
  const cust = await q1("SELECT * FROM customers WHERE id = ? AND tenant_id = ?", [me.id, req.user.tenant_id]);
  if (!cust) {
    res.status(404).json({ error: "Customer profile not found" });
    return;
  }
  const applications = await q(
    `SELECT a.id, a.application_no, a.status, a.stage, a.requested_amount, a.created_at, p.name AS product_name
     FROM applications a JOIN products p ON p.id = a.product_id
     WHERE a.customer_id = ? ORDER BY a.id DESC LIMIT 10`,
    [me.id]
  );
  const loans = await q(
    `SELECT l.id, l.loan_no, l.principal, l.outstanding, l.emi, l.dpd, l.status, l.disbursed_at, l.first_emi_at, p.name AS product_name
     FROM loans l JOIN products p ON p.id = l.product_id WHERE l.customer_id = ? ORDER BY l.id DESC LIMIT 10`,
    [me.id]
  );
  const nextDue = await q1(
    `SELECT i.due_date, i.total, i.paid_amount FROM installments i JOIN loans l ON l.id = i.loan_id
     WHERE l.customer_id = ? AND i.paid = 0 ORDER BY i.seq LIMIT 1`,
    [me.id]
  );
  const docsPending = await q1("SELECT COUNT(*) AS n FROM documents WHERE customer_id = ? AND status NOT IN ('verified','rejected')", [me.id]);
  const complaints = await q("SELECT id, complaint_no, category, status, created_at FROM complaints WHERE customer_id = ? ORDER BY id DESC LIMIT 5", [me.id]);
  const notifs = await q("SELECT id, title, body, created_at, read FROM notifications WHERE user_id = ? OR (user_id IS NULL AND tenant_id = ?) ORDER BY id DESC LIMIT 8", [req.user.id, req.user.tenant_id]);
  const activeLoans = loans.filter((l) => ["active", "overdue", "restructured"].includes(l.status));
  const totalOutstanding = activeLoans.reduce((s, l) => s + (l.outstanding ?? 0), 0);
  res.json({
    customer: { id: cust.id, name: cust.name, customer_no: cust.customer_no, kyc_status: cust.kyc_status },
    applications,
    loans,
    next_due: nextDue ?? null,
    docs_pending: docsPending?.n ?? 0,
    complaints,
    notifications: notifs,
    totals: { active_loans: activeLoans.length, outstanding: totalOutstanding }
  });
}));
