collectionsRouter.get("/collections/dashboard", requirePerm("collections.view"), asyncH(async (req, res) => {
  const t = req.user.tenant_id;
  const totalDue = await q1(
    `SELECT COALESCE(SUM(i.total - i.paid_amount), 0) AS due FROM installments i JOIN loans l ON l.id = i.loan_id
     WHERE l.tenant_id = ? AND i.paid = 0 AND i.due_date <= date('now')`,
    [t]
  );
  const collected = await q1(
    `SELECT COALESCE(SUM(pa.amount), 0) AS collected FROM payment_allocations pa JOIN payments p ON p.id = pa.payment_id
     WHERE p.tenant_id = ? AND p.reversed = 0 AND date(p.received_at) >= date('now', '-30 days')`,
    [t]
  );
  const overdue = await q1(`SELECT COALESCE(SUM(outstanding), 0) AS v, COUNT(*) AS n FROM loans WHERE tenant_id = ? AND status = 'overdue'`, [t]);
  const npa = await q1(`SELECT COALESCE(SUM(outstanding), 0) AS v, COUNT(*) AS n FROM loans WHERE tenant_id = ? AND npa_class IS NOT NULL`, [t]);
  const portfolio = await q1(`SELECT COALESCE(SUM(outstanding), 0) AS v FROM loans WHERE tenant_id = ? AND status NOT IN ('closed','written_off')`, [t]);
  const ptpStats = await q1(
    `SELECT COUNT(*) AS total, SUM(CASE WHEN p.status = 'kept' THEN 1 ELSE 0 END) AS kept, SUM(CASE WHEN p.status = 'broken' THEN 1 ELSE 0 END) AS broken
     FROM ptps p JOIN loans l ON l.id = p.loan_id WHERE l.tenant_id = ? AND p.created_at >= datetime('now', '-30 days')`,
    [t]
  );
  const bucketDist = await q(
    `SELECT CASE WHEN l.dpd = 0 THEN '0' WHEN l.dpd = 1 THEN '1-30' WHEN l.dpd = 2 THEN '31-60' WHEN l.dpd = 3 THEN '61-90' ELSE '90+' END AS bucket,
       COUNT(*) AS loans, COALESCE(SUM(l.outstanding), 0) AS outstanding
     FROM loans l WHERE l.tenant_id = ? AND l.status NOT IN ('closed','written_off') GROUP BY bucket ORDER BY MIN(l.dpd)`,
    [t]
  );
  const agentPerformance = await q(
    `SELECT u.name, COUNT(DISTINCT ct.id) AS tasks, SUM(CASE WHEN ct.status = 'done' THEN 1 ELSE 0 END) AS done,
            COUNT(DISTINCT p.id) AS payments, COALESCE(SUM(CASE WHEN p.reversed = 0 THEN p.amount ELSE 0 END), 0) AS collected_amount
     FROM collection_tasks ct
     LEFT JOIN users u ON u.id = ct.agent_id
     LEFT JOIN payments p ON p.recorded_by = u.id
     WHERE ct.tenant_id = ? GROUP BY u.id, u.name ORDER BY done DESC LIMIT 10`,
    [t]
  );
  const collectionEfficiency = portfolio.v > 0 ? Math.round(collected.collected / portfolio.v * 1e3) / 10 : 0;
  res.json({
    totalDue: totalDue.due,
    collected30d: collected.collected,
    overdue,
    npa,
    portfolio: portfolio.v,
    ptp: ptpStats,
    bucketDist,
    agentPerformance,
    collectionEfficiency
  });
}));
