collectionsRouter.post("/collections/loans/:id/writeoff", requirePerm("recovery.*"), asyncH(async (req, res) => {
  const body = z11.object({ amount: z11.number().int().positive(), reason: z11.string() }).parse(req.body);
  const loan = await q1("SELECT * FROM loans WHERE id = ? AND tenant_id = ?", [req.params.id, req.user.tenant_id]);
  if (!loan) {
    res.status(404).json({ error: "Loan not found" });
    return;
  }
  const id = (await run("INSERT INTO writeoffs (loan_id, amount, reason, status) VALUES (?, ?, ?, 'requested')", [loan.id, body.amount, body.reason])).lastId;
  await audit({ tenantId: req.user.tenant_id, userId: req.user.id, action: "writeoff.request", entityType: "writeoff", entityId: id, after: body, ip: clientIp(req) });
  res.json({ id });
}));
collectionsRouter.post("/collections/writeoffs/:id/approve", requirePerm("recovery.approve"), asyncH(async (req, res) => {
  const w = await q1("SELECT * FROM writeoffs WHERE id = ?", [req.params.id]);
  if (!w) {
    res.status(404).json({ error: "Write-off not found" });
    return;
  }
  const loan = await q1("SELECT * FROM loans WHERE id = ?", [w.loan_id]);
  await run("INSERT INTO approvals (tenant_id, entity_type, entity_id, action, status, by_user) VALUES (?, 'writeoff', ?, 'writeoff', 'approved', ?)", [loan.tenant_id, w.id, req.user.id]);
  await run("UPDATE writeoffs SET status = 'posted', approved_by = ? WHERE id = ?", [req.user.id, w.id]);
  await run("UPDATE loans SET written_off = 1, status = 'written_off' WHERE id = ?", [loan.id]);
  await recordLoanEvent(loan.id, "writeoff", { tenantId: loan.tenant_id, amount: w.amount, reference: loan.loan_no, data: { writeoff_id: w.id, reason: w.reason }, userId: req.user.id });
  await run("INSERT INTO notifications (tenant_id, title, body) VALUES (?, 'Loan written off', ?)", [loan.tenant_id, `${loan.loan_no} written off (${inrShort4(w.amount)})`]);
  await audit({ tenantId: loan.tenant_id, userId: req.user.id, action: "writeoff.approve", entityType: "writeoff", entityId: w.id, after: { amount: w.amount }, ip: clientIp(req) });
  res.json({ ok: true });
}));
function inrShort4(n) {
  return "\u20B9" + n.toLocaleString("en-IN");
}

// server/src/routes/gn.ts
init_connection();
import { Router as Router12 } from "express";
import { z as z12 } from "zod";
init_gn();
var gnRouter = Router12();
gnRouter.use(authRequired);
var T2 = (req) => req.user.tenant_id;
gnRouter.get("/gn/dashboard", requirePerm("gn.view"), asyncH(async (req, res) => {
  const t = T2(req);
  const one = async (sql, params = []) => await q1(sql, params);
  const apps = await one(
    `SELECT COUNT(*) AS total,
       SUM(CASE WHEN stage IN ('lender','agreement','disbursement','completed','closed') THEN 1 ELSE 0 END) AS submitted,
       SUM(CASE WHEN status IN ('approved','sanction_generated','agreement_pending','esign_pending','agreement_completed','disb_pending','disb_initiated','disb_partial','disb_fully','disb_confirmed','payout_pending','payout_received','closed') THEN 1 ELSE 0 END) AS approved,
       SUM(CASE WHEN status = 'rejected' THEN 1 ELSE 0 END) AS rejected,
       SUM(CASE WHEN disbursed_amount > 0 THEN 1 ELSE 0 END) AS disbursed
     FROM gn_applications WHERE tenant_id = ?`,
    [t]
  );
  const disbursement = await one("SELECT COALESCE(SUM(disbursed_amount), 0) AS total FROM gn_applications WHERE tenant_id = ? AND disbursed_amount > 0", [t]);
  const commissions = await one(
    `SELECT COALESCE(SUM(gross), 0) AS gross, COALESCE(SUM(CASE WHEN status = 'received' THEN gross ELSE 0 END), 0) AS received,
       COALESCE(SUM(net), 0) AS net FROM gn_commissions WHERE tenant_id = ?`,
    [t]
  );
  const receivable = await one("SELECT COALESCE(SUM(gross), 0) AS total FROM gn_commissions WHERE tenant_id = ? AND status = 'earned'", [t]);
  const aging = await q(
    `SELECT CASE WHEN julianday('now') - julianday(created_at) <= 30 THEN '0-30'
                 WHEN julianday('now') - julianday(created_at) <= 60 THEN '31-60'
                 WHEN julianday('now') - julianday(created_at) <= 90 THEN '61-90'
                 ELSE '90+' END AS bucket, COALESCE(SUM(gross), 0) AS amount, COUNT(*) AS n
     FROM gn_commissions WHERE tenant_id = ? AND status = 'earned' GROUP BY bucket`,
    [t]
  );
  const byLender = await q(
    `SELECT l.name, COUNT(a.id) AS apps, COALESCE(SUM(a.disbursed_amount), 0) AS disbursed, COALESCE(SUM(a.commission_gross), 0) AS commission
     FROM gn_applications a JOIN gn_lenders l ON l.id = a.lender_id WHERE a.tenant_id = ?
     GROUP BY l.id ORDER BY disbursed DESC LIMIT 6`,
    [t]
  );
  const byPartner = await q(
    `SELECT p.name, COUNT(a.id) AS apps, COALESCE(SUM(a.disbursed_amount), 0) AS disbursed
     FROM gn_applications a JOIN gn_partners p ON p.id = a.partner_id WHERE a.tenant_id = ?
     GROUP BY p.id ORDER BY disbursed DESC LIMIT 6`,
    [t]
  );
  const funnel = await q(
    `SELECT stage, COUNT(*) AS n FROM gn_applications WHERE tenant_id = ? GROUP BY stage`,
    [t]
  );
  const trend = await q(
    `SELECT substr(disbursed_at, 1, 7) AS month, COALESCE(SUM(disbursed_amount), 0) AS amount, COUNT(*) AS loans
     FROM gn_applications WHERE tenant_id = ? AND disbursed_amount > 0 GROUP BY month ORDER BY month DESC LIMIT 6`,
    [t]
  );
  const campaigns = await q("SELECT * FROM gn_campaigns WHERE tenant_id = ? ORDER BY id DESC LIMIT 5", [t]);
  const partners = await one("SELECT COUNT(*) AS n FROM gn_partners WHERE tenant_id = ? AND status = 'active'", [t]);
  const settings = await gnSettings(t);
  res.json({
    applications: { ...apps, pending: (apps?.total ?? 0) - (apps?.submitted ?? 0) },
    disbursement: disbursement?.total ?? 0,
    commissions,
    receivable: receivable?.total ?? 0,
    aging,
    byLender,
    byPartner,
    funnel,
    trend: trend.reverse(),
    campaigns,
    activePartners: partners?.n ?? 0,
    settings
  });
}));
gnRouter.get("/gn/lenders", requirePerm("gn.masters.view"), asyncH(async (req, res) => {
  const rows = await q(
    `SELECT l.*,
       (SELECT COUNT(*) FROM gn_products p WHERE p.lender_id = l.id) AS products,
       (SELECT COUNT(*) FROM gn_applications a WHERE a.lender_id = l.id) AS applications,
       (SELECT COALESCE(SUM(a.disbursed_amount), 0) FROM gn_applications a WHERE a.lender_id = l.id) AS disbursed
     FROM gn_lenders l WHERE l.tenant_id = ? ORDER BY l.name`,
    [T2(req)]
  );
  res.json(rows);
}));
var lenderSchema = z12.object({
  name: z12.string().min(2),
  type: z12.string().optional(),
  dsa_code: z12.string().optional(),
  contact_person: z12.string().optional(),
  contact_phone: z12.string().optional(),
  contact_email: z12.string().optional(),
  gst_policy: z12.string().optional(),
  api_status: z12.string().optional(),
  status: z12.string().optional()
});
gnRouter.post("/gn/lenders", requirePerm("gn.masters.manage"), asyncH(async (req, res) => {
  const b = lenderSchema.parse(req.body);
  const id = (await run(
    "INSERT INTO gn_lenders (tenant_id, name, type, dsa_code, contact_person, contact_phone, contact_email, gst_policy, api_status, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
    [T2(req), b.name, b.type ?? "Bank", b.dsa_code ?? null, b.contact_person ?? null, b.contact_phone ?? null, b.contact_email ?? null, b.gst_policy ?? "client", b.api_status ?? "mock", b.status ?? "active"]
  )).lastId;
  await audit({ tenantId: T2(req), userId: req.user.id, action: "gn.lender.create", entityType: "gn_lender", entityId: id, after: b, ip: clientIp(req) });
  res.json(await q1("SELECT * FROM gn_lenders WHERE id = ?", [id]));
}));
gnRouter.patch("/gn/lenders/:id", requirePerm("gn.masters.manage"), asyncH(async (req, res) => {
  const b = lenderSchema.partial().parse(req.body);
  const before = await q1("SELECT * FROM gn_lenders WHERE id = ? AND tenant_id = ?", [req.params.id, T2(req)]);
  if (!before) {
    res.status(404).json({ error: "Lender not found" });
    return;
  }
  const sets = Object.keys(b).map((k) => `${k} = ?`);
  await run(`UPDATE gn_lenders SET ${sets.join(", ")} WHERE id = ?`, [...Object.values(b), before.id]);
  await audit({ tenantId: T2(req), userId: req.user.id, action: "gn.lender.update", entityType: "gn_lender", entityId: before.id, before, after: b, ip: clientIp(req) });
  res.json(await q1("SELECT * FROM gn_lenders WHERE id = ?", [before.id]));
}));
gnRouter.get("/gn/products", requirePerm("gn.masters.view"), asyncH(async (req, res) => {
  const { lender_id, category } = req.query;
  const where = ["p.tenant_id = ?"];
  const params = [T2(req)];
  if (lender_id) {
    where.push("p.lender_id = ?");
    params.push(Number(lender_id));
  }
  if (category) {
    where.push("p.category = ?");
    params.push(category);
  }
  const rows = await q(
    `SELECT p.*, l.name AS lender_name FROM gn_products p JOIN gn_lenders l ON l.id = p.lender_id
     WHERE ${where.join(" AND ")} ORDER BY p.category, p.name`,
    params
  );
  const categories = await q("SELECT category, COUNT(*) AS n FROM gn_products WHERE tenant_id = ? GROUP BY category ORDER BY n DESC", [T2(req)]);
  res.json({ rows, categories });
}));
