gnRouter.post("/gn/match", requirePerm("gn.view"), asyncH(async (req, res) => {
  const b = z12.object({
    loan_type: z12.string().optional(),
    amount: z12.number(),
    tenure: z12.number().optional(),
    employment_type: z12.string().optional(),
    monthly_income: z12.number().nullable().optional(),
    business_turnover: z12.number().nullable().optional(),
    business_vintage: z12.number().nullable().optional(),
    city: z12.string().optional(),
    state: z12.string().optional()
  }).parse(req.body);
  const products = await q(
    `SELECT p.*, l.name AS lender_name, l.api_status FROM gn_products p JOIN gn_lenders l ON l.id = p.lender_id
     WHERE p.tenant_id = ? AND p.status = 'active'`,
    [T2(req)]
  );
  const matches = products.map((p) => {
    const reasons = [];
    let eligible = true;
    if (b.loan_type && p.category.toLowerCase() !== b.loan_type.toLowerCase() && !p.name.toLowerCase().includes(b.loan_type.toLowerCase())) {
      eligible = false;
      reasons.push(`Category ${p.category} \u2260 requested ${b.loan_type}`);
    }
    if (b.amount < p.min_amount || b.amount > p.max_amount) {
      eligible = false;
      reasons.push(`Amount \u20B9${p.min_amount.toLocaleString("en-IN")}\u2013\u20B9${p.max_amount.toLocaleString("en-IN")}`);
    }
    if (b.business_turnover != null && p.min_turnover && b.business_turnover < p.min_turnover) {
      eligible = false;
      reasons.push(`Turnover below \u20B9${p.min_turnover.toLocaleString("en-IN")}`);
    }
    if (b.business_vintage != null && p.min_vintage && b.business_vintage < p.min_vintage) {
      eligible = false;
      reasons.push(`Vintage below ${p.min_vintage} yrs`);
    }
    if (b.monthly_income != null && p.min_income && b.monthly_income < p.min_income) {
      eligible = false;
      reasons.push(`Income below \u20B9${p.min_income.toLocaleString("en-IN")}/mo`);
    }
    let status = eligible ? "eligible" : "not_eligible";
    if (status === "eligible" && p.required_documents.length > 3) status = "additional_docs";
    return {
      product: p.name,
      category: p.category,
      lender: p.lender_name,
      api_status: p.api_status,
      payout_pct: p.payout_pct,
      roi: p.roi_min && p.roi_max ? `${p.roi_min}\u2013${p.roi_max}%` : null,
      status,
      reasons: eligible ? [] : reasons
    };
  });
  res.json({ matches: matches.sort((a, b2) => (a.status === "eligible" ? -1 : 1) - (b2.status === "eligible" ? -1 : 1)) });
}));
