gnRouter.post("/gn/hr/payroll/generate", requirePerm("gn.hr.manage"), asyncH(async (req, res) => {
  const b = z12.object({ month: z12.string() }).parse(req.body);
  const users = await q("SELECT id, role FROM users WHERE tenant_id = ?", [T2(req)]);
  let n = 0;
  for (const u of users) {
    const roleBase = { tenant_admin: 12e4, branch_admin: 9e4, sales_manager: 7e4, credit_manager: 95e3, credit_analyst: 65e3, underwriter: 65e3, operations: 55e3, collection_manager: 55e3, collection_agent: 3e4, telecaller: 22e3, field_executive: 3e4, finance: 6e4, dsa: 0, auditor: 7e4, compliance_officer: 75e3, customer_support: 25e3, customer: 0 };
    const gross = roleBase[u.role] ?? 4e4;
    if (gross === 0) continue;
    const tds = Math.round(gross * 0.02);
    await run(
      "INSERT OR IGNORE INTO gn_payroll (tenant_id, user_id, month, basic, hra, allowance, gross, tds, net) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
      [T2(req), u.id, b.month, Math.round(gross * 0.5), Math.round(gross * 0.3), Math.round(gross * 0.2), gross, tds, gross - tds]
    );
    n++;
  }
  res.json({ generated: n, month: b.month });
}));
