gnRouter.post("/gn/utility/leads/assign", requirePerm("gn.leads.manage"), asyncH(async (req, res) => {
  const t = T2(req);
  const b = z12.object({
    status: z12.string().optional(),
    city: z12.string().optional(),
    state: z12.string().optional(),
    loan_type: z12.string().optional(),
    assigned_to: z12.number().nullable().optional(),
    search: z12.string().optional(),
    target_user_id: z12.number().int().positive(),
    dry_run: z12.boolean().optional()
  }).parse(req.body);
  const where = ["l.tenant_id = ?"];
  const params = [t];
  if (b.status) {
    where.push("l.status = ?");
    params.push(b.status);
  }
  if (b.city) {
    where.push("l.city = ?");
    params.push(b.city);
  }
  if (b.state) {
    where.push("l.state = ?");
    params.push(b.state);
  }
  if (b.loan_type) {
    where.push("l.loan_type = ?");
    params.push(b.loan_type);
  }
  if (b.assigned_to) {
    where.push("l.owner_id = ?");
    params.push(b.assigned_to);
  }
  if (b.search) {
    where.push("(l.name LIKE ? OR l.mobile LIKE ? OR l.email LIKE ?)");
    const like = `%${b.search}%`;
    params.push(like, like, like);
  }
  const target = await q1("SELECT id, name FROM users WHERE id = ? AND tenant_id = ?", [b.target_user_id, t]);
  if (!target) {
    res.status(400).json({ error: "Target team member not found" });
    return;
  }
  const affected = await q1(
    `SELECT COUNT(*) AS n, COALESCE(SUM(l.requested_amount), 0) AS amount FROM leads l WHERE ${where.join(" AND ")}`,
    params
  );
  if (b.dry_run) {
    res.json({ dryRun: true, count: affected?.n ?? 0, amount: affected?.amount ?? 0, target: target.name });
    return;
  }
  const match = await q(`SELECT l.id FROM leads l WHERE ${where.join(" AND ")}`, params);
  for (const row of match) {
    await run("UPDATE leads SET owner_id = ?, updated_at = datetime('now') WHERE id = ?", [b.target_user_id, row.id]);
  }
  await audit({ tenantId: t, userId: req.user.id, action: "gn.utility.leads.assign", entityType: "lead", entityId: 0, before: b, after: { count: match.length, target: target.name }, ip: clientIp(req) });
  res.json({ assigned: match.length, target: target.name });
}));
