gnRouter.post("/gn/workflows/:id/run", requirePerm("gn.marketing.manage"), asyncH(async (req, res) => {
  const w = await q1("SELECT * FROM gn_workflows WHERE id = ? AND tenant_id = ?", [req.params.id, T2(req)]);
  if (!w) {
    res.status(404).json({ error: "Workflow not found" });
    return;
  }
  const actions = JSON.parse(w.actions || "[]");
  const leads = await q(
    `SELECT id, name, mobile FROM leads WHERE tenant_id = ? AND status IN ('new','assigned','contacted') LIMIT 3`,
    [T2(req)]
  );
  let enqueued = 0;
  for (const l of leads) {
    for (const a of actions) {
      if (a.type === "whatsapp" || a.type === "email") {
        const tpl = a.template_id ? await q1("SELECT name, body FROM gn_message_templates WHERE id = ? AND tenant_id = ?", [a.template_id, T2(req)]) : null;
        await run(
          "INSERT INTO gn_inbox_messages (tenant_id, direction, channel, to_contact, subject, body, related_type, related_id, status, created_by) VALUES (?, 'out', ?, ?, ?, ?, 'lead', ?, 'sent', ?)",
          [T2(req), a.type === "whatsapp" ? "whatsapp" : "email", l.mobile, tpl?.name ?? w.name, tpl?.body ?? `Hi ${l.name}, your loan journey with Growth Nations is moving forward.`, l.id, req.user.id]
        );
        enqueued++;
      }
      if (a.type === "task") {
        await run(
          "INSERT INTO gn_tasks (tenant_id, title, linked_to, priority, status, due_at, assigned_to, created_by) VALUES (?, ?, ?, 'high', 'pending', datetime('now', '+1 day'), ?, ?)",
          [T2(req), a.title ?? `Follow up ${l.name}`, `lead-${l.id}`, req.user.id, req.user.id]
        );
        enqueued++;
      }
    }
  }
  await run("UPDATE gn_workflows SET run_count = run_count + 1, last_run_at = datetime('now') WHERE id = ?", [w.id]);
  await audit({ tenantId: T2(req), userId: req.user.id, action: "gn.workflow.run", entityType: "gn_workflow", entityId: w.id, after: { leads: leads.length, enqueued }, ip: clientIp(req) });
  res.json({ ok: true, leads: leads.length, enqueued, runCount: (w.run_count ?? 0) + 1 });
}));
