gnRouter.post("/gn/inbox/drips/:id/send", requirePerm("gn.inbox.manage"), asyncH(async (req, res) => {
  const t = T2(req);
  const d = await q1("SELECT * FROM gn_whatsapp_drips WHERE id = ? AND tenant_id = ?", [req.params.id, t]);
  if (!d) {
    res.status(404).json({ error: "Drip not found" });
    return;
  }
  const tpl = d.template_id ? await q1("SELECT name, body FROM gn_message_templates WHERE id = ? AND tenant_id = ?", [d.template_id, t]) : null;
  const audience = d.audience === "disb_only" ? await q("SELECT id, name, mobile FROM leads WHERE tenant_id = ? AND status = 'disbursed' LIMIT 5", [t]) : d.audience === "overdue" ? await q("SELECT id, name, mobile FROM leads WHERE tenant_id = ? AND status = 'overdue' LIMIT 5", [t]) : await q("SELECT id, name, mobile FROM leads WHERE tenant_id = ? AND status IN ('new','assigned','contacted','followup') LIMIT 5", [t]);
  let sent = 0;
  for (const l of audience) {
    await run(
      "INSERT INTO gn_inbox_messages (tenant_id, direction, channel, to_contact, subject, body, related_type, related_id, status, created_by) VALUES (?, 'out', 'whatsapp', ?, ?, ?, 'lead', ?, 'sent', ?)",
      [t, l.mobile, tpl?.name ?? d.name, tpl?.body ?? `Hi ${l.name}, here's your loan update from Growth Nations.`, l.id, req.user.id]
    );
    sent++;
  }
  await run("UPDATE gn_whatsapp_drips SET sent_count = sent_count + ?, delivered_count = delivered_count + ? WHERE id = ?", [sent, Math.max(1, Math.round(sent * 0.9)), d.id]);
  await audit({ tenantId: t, userId: req.user.id, action: "gn.drip.send", entityType: "gn_drip", entityId: d.id, after: { sent, template: tpl?.name ?? null }, ip: clientIp(req) });
  res.json({ ok: true, sent });
}));
