function safeJson2(v, dflt) {
  try {
    const p = JSON.parse(v);
    return p ?? dflt;
  } catch {
    return dflt;
  }
}
var TRASH_TABLES = {
  campaign: "gn_campaigns",
  task: "gn_tasks",
  document: "gn_documents",
  scheme: "gn_schemes",
  doc: "gn_docs",
  template: "gn_message_templates",
  workflow: "gn_workflows",
  ivr_menu: "gn_ivr_menus",
  drip: "gn_whatsapp_drips",
  faq: "gn_faqs",
  changelog: "gn_changelog",
  message: "gn_inbox_messages"
};
var TRASH_NAMES = {
  campaign: "name",
  task: "title",
  document: "name",
  scheme: "name",
  doc: "title",
  template: "name",
  workflow: "name",
  ivr_menu: "name",
  drip: "name",
  faq: "question",
  changelog: "title",
  message: "subject"
};
async function trashEntity(t, uid, ip, entityType, entityId) {
  const table = TRASH_TABLES[entityType];
  if (!table) return false;
  const row = await q1(`SELECT * FROM ${table} WHERE id = ? AND tenant_id = ?`, [entityId, t]);
  if (!row) return false;
  await run(`DELETE FROM ${table} WHERE id = ?`, [entityId]);
  await run(
    "INSERT INTO gn_trash (tenant_id, entity_type, entity_id, name, payload, deleted_by) VALUES (?, ?, ?, ?, ?, ?)",
    [t, entityType, entityId, row[TRASH_NAMES[entityType]] ?? String(entityId), JSON.stringify({ table, row }), uid]
  );
  await audit({ tenantId: t, userId: uid, action: "gn.trash.add", entityType, entityId, before: row, ip });
  return true;
}
gnRouter.get("/gn/trash", requirePerm("gn.trash.view"), asyncH(async (req, res) => {
  const { entity_type, q: search } = req.query;
  const where = ["tr.tenant_id = ?", "tr.restored_at IS NULL"];
  const params = [T2(req)];
  if (entity_type) {
    where.push("tr.entity_type = ?");
    params.push(entity_type);
  }
  if (search) {
    where.push("(tr.name LIKE ? OR tr.entity_type LIKE ?)");
    const like = `%${search}%`;
    params.push(like, like);
  }
  const rows = await q(
    `SELECT tr.*, u.name AS deleted_name FROM gn_trash tr LEFT JOIN users u ON u.id = tr.deleted_by
     WHERE ${where.join(" AND ")} ORDER BY tr.deleted_at DESC`,
    params
  );
  const summary = await q("SELECT entity_type, COUNT(*) AS n FROM gn_trash WHERE tenant_id = ? GROUP BY entity_type", [T2(req)]);
  res.json({ rows, summary });
}));
gnRouter.post("/gn/trash/:id/restore", requirePerm("gn.trash.manage"), asyncH(async (req, res) => {
  const t = T2(req);
  const item = await q1("SELECT * FROM gn_trash WHERE id = ? AND tenant_id = ?", [req.params.id, t]);
  if (!item) {
    res.status(404).json({ error: "Trash item not found" });
    return;
  }
  const payload = safeJson2(item.payload, null);
  if (!payload?.table || !TRASH_TABLES[item.entity_type] || payload.table !== TRASH_TABLES[item.entity_type]) {
    res.status(400).json({ error: "Corrupt trash payload" });
    return;
  }
  const row = payload.row ?? {};
  const cols = Object.keys(row).filter((k) => /^[a-z_]+$/.test(k) && k !== "id");
  let restoredId = row.id;
  try {
    await run(`INSERT INTO ${payload.table} (id, ${cols.join(", ")}) VALUES (?, ${cols.map(() => "?").join(", ")})`, [row.id, ...cols.map((c) => row[c])]);
  } catch {
    restoredId = (await run(`INSERT INTO ${payload.table} (${cols.join(", ")}) VALUES (${cols.map(() => "?").join(", ")})`, cols.map((c) => row[c]))).lastId;
  }
  await run("DELETE FROM gn_trash WHERE id = ?", [item.id]);
  await audit({ tenantId: t, userId: req.user.id, action: "gn.trash.restore", entityType: item.entity_type, entityId: item.entity_id, before: { trashId: item.id }, after: { restoredId }, ip: clientIp(req) });
  res.json({ ok: true, restoredId, entityType: item.entity_type });
}));
