gnAdminRouter.post("/gn/import/schemes/file", requirePerm("gn.*"), asyncH(async (req, res) => {
  const t = T3(req);
  const b = z13.object({ filename: z13.string().min(1), mime: z13.string().optional(), data: z13.string() }).parse(req.body);
  const buf = Buffer.from(b.data, "base64");
  const ext = (b.filename.split(".").pop() || "").toLowerCase();
  const lenderByName = new Map((await q("SELECT id, name FROM gn_lenders WHERE tenant_id = ?", [t]) ?? []).map((r) => [r.name, r.id]));
  const inserted = [];
  const errors = [];
  let format = ext;
  let pending = false;
  let notes = null;
  try {
    if (["csv", "tsv"].includes(ext)) {
      const text = buf.toString("utf8").replace(/^\uFEFF/, "");
      const rows = parseCsv2(ext === "tsv" ? text.replace(/\t/g, ",") : text);
      for (const [i, row] of rows.entries()) {
        try {
          inserted.push(await importSchemeRow(t, row, lenderByName, `import:${ext}`));
        } catch (e) {
          errors.push({ row: i + 1, error: e.message });
        }
      }
    } else if (ext === "json") {
      const parsed = JSON.parse(buf.toString("utf8"));
      const rows = Array.isArray(parsed) ? parsed : parsed.rows ?? [];
      for (const [i, row] of rows.entries()) {
        try {
          inserted.push(await importSchemeRow(t, row, lenderByName, "import:json"));
        } catch (e) {
          errors.push({ row: i + 1, error: e.message });
        }
      }
    } else if (["xlsx", "xls"].includes(ext)) {
      const wb = XLSX.read(buf, { type: "buffer" });
      const sheet = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(sheet, { defval: "" });
      for (const [i, row] of rows.entries()) {
        try {
          inserted.push(await importSchemeRow(t, row, lenderByName, "import:xlsx"));
        } catch (e) {
          errors.push({ row: i + 1, error: e.message });
        }
      }
    } else {
      pending = true;
      format = "document";
      notes = "Document stored \u2014 automatic text extraction is not available for this format in the demo. Review it and add the scheme via the form.";
      await run(
        "INSERT INTO gn_scheme_files (tenant_id, kind, filename, mime, size, content, status, notes) VALUES (?, 'scheme_document', ?, ?, ?, ?, 'pending_review', ?)",
        [t, b.filename, b.mime || "application/octet-stream", buf.length, b.data, notes]
      );
    }
  } catch (e) {
    return void res.status(400).json({ error: e.message });
  }
  const attachment = (await q1("SELECT id FROM gn_scheme_files WHERE tenant_id = ? ORDER BY id DESC LIMIT 1", [t]))?.id ?? null;
  await audit({ tenantId: t, userId: req.user.id, action: "gn.scheme.import_file", entityType: "gn_scheme_import", after: { filename: b.filename, format, inserted: inserted.length, errors: errors.length, pending }, ip: clientIp(req) });
  res.json({ ok: true, format, filename: b.filename, inserted: inserted.length, errors, pending, attachment, notes });
}));

