gnPipelineRouter.get("/gn/applications", requirePerm("gn.applications.view"), asyncH(async (req, res) => {
  const { status, stage, lender_id, partner_id, q: query, source, page = 1, limit = 25, sort = "created_at", dir = "desc" } = req.query;
  const where = ["a.tenant_id = ?"];
  const params = [T4(req)];
  if (status) {
    where.push("a.status = ?");
    params.push(status);
  }
  if (stage) {
    where.push("a.stage = ?");
    params.push(stage);
  }
  if (lender_id) {
    where.push("a.lender_id = ?");
    params.push(Number(lender_id));
  }
  if (partner_id) {
    where.push("a.partner_id = ?");
    params.push(Number(partner_id));
  }
  if (source) {
    where.push("a.source = ?");
    params.push(source);
  }
  if (query) {
    where.push("(a.ref LIKE ? OR a.name LIKE ? OR a.mobile LIKE ?)");
    params.push(`%${query}%`, `%${query}%`, `%${query}%`);
  }
  const total = (await q1(`SELECT COUNT(*) AS n FROM gn_applications a WHERE ${where.join(" AND ")}`, params)).n;
  const off = (Math.max(1, Number(page)) - 1) * Number(limit);
  const rows = await q(
    `SELECT a.*, l.name AS lender_name, p.name AS product_name, p.category AS product_category,
       pt.name AS partner_name, pt.type AS partner_type, u.name AS assigned_name
     FROM gn_applications a
     LEFT JOIN gn_lenders l ON l.id = a.lender_id
     LEFT JOIN gn_products p ON p.id = a.product_id
     LEFT JOIN gn_partners pt ON pt.id = a.partner_id
     LEFT JOIN users u ON u.id = a.assigned_to
     WHERE ${where.join(" AND ")}
     ORDER BY a.${["created_at", "disbursed_at", "amount", "name"].includes(sort) ? sort : "created_at"} ${dir === "asc" ? "ASC" : "DESC"}
     LIMIT ? OFFSET ?`,
    [...params, Number(limit), off]
  );
  const counts = await q1(
    `SELECT COUNT(*) AS total,
       SUM(CASE WHEN stage = 'lender' THEN 1 ELSE 0 END) AS at_lender,
       SUM(CASE WHEN disbursed_amount > 0 THEN 1 ELSE 0 END) AS disbursed,
       SUM(CASE WHEN status = 'rejected' THEN 1 ELSE 0 END) AS rejected
     FROM gn_applications WHERE tenant_id = ?`,
    [T4(req)]
  );
  res.json({ rows, total, page: Number(page), limit: Number(limit), counts });
}));
