adminRouter.post("/bre/simulate", requirePerm("bre.simulate"), asyncH(async (req, res) => {
  const body = z18.object({ conditions: z18.any(), action: z18.any().optional() }).parse(req.body);
  const apps = await q("SELECT id FROM applications WHERE tenant_id = ? AND status != 'rejected' LIMIT 300", [req.user.tenant_id]);
  const results = await Promise.all(apps.map(async (a) => {
    const ctx = await buildApplicationContext(a.id);
    const rule = { code: "SIM", name: "Simulated rule", category: "credit_policy", priority: 1, conditions: body.conditions, action: body.action ?? {} };
    const r = evaluateRuleSet([rule], ctx);
    return { applicationId: a.id, eligible: r.eligible, riskGrade: r.riskGrade, reason: r.reasons[0] };
  }));
  const affected = results.filter((r) => !r.eligible).length;
  res.json({ simulated: results.length, affected, impactPct: results.length ? Math.round(affected / results.length * 1e3) / 10 : 0, results: results.slice(0, 50) });
}));
