adminRouter.patch("/integrations/:id", requirePerm("admin.integrations"), asyncH(async (req, res) => {
  const body = z18.object({
    mode: z18.enum(["mock", "live"]).optional(),
    status: z18.string().optional(),
    provider: z18.string().optional()
  }).parse(req.body);
  const before = await q1("SELECT * FROM integrations WHERE id = ? AND tenant_id = ?", [req.params.id, req.user.tenant_id]);
  if (!before) {
    res.status(404).json({ error: "Integration not found" });
    return;
  }
  const adapter = CATALOG_BY_CODE.get(before.code);
  const cfg = parseRowConfig(before);
  const mode = body.mode ?? (cfg.mode === "live" ? "live" : "mock");
  const config = { ...cfg, mode, sandbox: mode !== "live" };
  const provider = body.mode === "live" ? "DIGITAP" : body.provider ?? `MOCK-${before.code.toUpperCase()}`;
  await run(
    "UPDATE integrations SET status = ?, provider = ?, config = ? WHERE id = ?",
    [mode === "live" ? "sandbox" : "sandbox", provider, JSON.stringify(config), before.id]
  );
  await audit({ tenantId: req.user.tenant_id, userId: req.user.id, action: `admin.integration_${mode}`, entityType: "integration", entityId: before.id, before, after: { mode, adapter: adapter?.name }, ip: clientIp(req) });
  res.json(buildIntegrationView({ ...before, status: "sandbox", provider, config: JSON.stringify(config) }));
}));
adminRouter.post("/integrations/:id/test", requirePerm("admin.integrations"), asyncH(async (req, res) => {
  const row = await q1("SELECT * FROM integrations WHERE id = ? AND tenant_id = ?", [req.params.id, req.user.tenant_id]);
  if (!row) {
    res.status(404).json({ error: "Integration not found" });
    return;
  }
  const adapter = CATALOG_BY_CODE.get(row.code);
  if (!adapter) {
    res.status(400).json({ error: "Unknown adapter code" });
    return;
  }
  const t0 = Date.now();
  let outcome;
  const probe = LIVE_PROBE_CODES.has(row.code) ? await PROBE_TARGETS[row.code]() : null;
  if (adapter.excluded) {
    outcome = { ok: false, message: "This adapter is out of live scope (Payments / Communication excluded by design)." };
  } else if (probe) {
    outcome = { ok: probe.ok, message: probe.message, detail: `env=${probe.auth ? digitapConfig().env.toUpperCase() : "\u2014"} \xB7 latency ${probe.latencyMs}ms` };
  } else if (!adapter.digitap?.enabled) {
    outcome = { ok: false, message: `Awaiting Digitap enablement \u2014 ${adapter.digitap?.family ?? "unknown suite"} (${adapter.digitap?.product ?? row.code}). ${adapter.digitap?.note ?? ""}` };
  } else {
    outcome = { ok: false, message: "Adapter suite not yet wired to a live driver." };
  }
  const cfg = parseRowConfig(row);
  const config = { ...cfg, lastTest: (/* @__PURE__ */ new Date()).toISOString(), lastTestOk: outcome.ok, lastTestMessage: outcome.message, lastTestLatencyMs: Date.now() - t0 };
  await run(
    "UPDATE integrations SET config = ?, status = ? WHERE id = ?",
    [JSON.stringify(config), outcome.ok ? adapter.excluded ? row.status : "connected" : "error", row.id]
  );
  await audit({ tenantId: req.user.tenant_id, userId: req.user.id, action: `admin.integration_test`, entityType: "integration", entityId: row.id, after: { code: row.code, ok: outcome.ok, message: outcome.message }, ip: clientIp(req) });
  res.json({ ok: outcome.ok, message: outcome.message, detail: outcome.detail, latencyMs: Date.now() - t0 });
}));
adminRouter.get("/audit", requirePerm("audit.view"), asyncH(async (req, res) => {
  const { q: query, page = 1, limit = 50 } = req.query;
  const where = ["al.tenant_id = ?"];
  const params = [req.user.tenant_id];
  if (query) {
    where.push("(al.action LIKE ? OR al.entity_type LIKE ?)");
    params.push(`%${query}%`, `%${query}%`);
  }
  const total = (await q1(`SELECT COUNT(*) AS n FROM audit_logs al WHERE ${where.join(" AND ")}`, params)).n;
  const rows = await q(
    `SELECT al.*, u.name AS by_name FROM audit_logs al LEFT JOIN users u ON u.id = al.user_id
     WHERE ${where.join(" AND ")} ORDER BY al.id DESC LIMIT ? OFFSET ?`,
    [...params, Number(limit), (Math.max(1, Number(page)) - 1) * Number(limit)]
  );
  res.json({ rows, total });
}));
