      UNDERWRITING: "underwriting",
      APPROVED: "approval",
      SANCTIONED: "sanction",
      AGREEMENT_PENDING: "agreement",
      ESIGN_PENDING: "esign",
      ESIGN_COMPLETED: "disbursement",
      DISBURSEMENT_PENDING: "disbursement",
      DISBURSED: "disbursement"
